@implements IAsyncDisposable
@inject IJSRuntime JS

<div @ref="_container">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }
    [Parameter] public int TimeoutSeconds { get; set; } = 300;
    [Parameter] public EventCallback OnIdle { get; set; }
    [Parameter] public EventCallback OnActive { get; set; }

    private ElementReference _container;
    private IJSObjectReference? _jsModule;
    private DotNetObjectReference<UserActivityTracker>? _dotNetRef;
    private System.Timers.Timer? _timer;
    private bool _isIdle;
    private bool _disposed;

    protected override void OnInitialized()
    {
        _timer = new System.Timers.Timer(TimeoutSeconds * 1000);
        _timer.AutoReset = false;
        _timer.Elapsed += OnTimerElapsed;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _jsModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-d147fb65ca984dbc93a9b3da79cd70cf/Components/UserActivityTracker.razor.js");
            await _jsModule.InvokeVoidAsync("initialize", _container, _dotNetRef);
            _timer?.Start();
        }
    }

    [JSInvokable]
    public void OnUserActivity()
    {
        if (_disposed) return;

        _timer?.Stop();
        _timer?.Start();

        if (_isIdle)
        {
            _isIdle = false;
            InvokeAsync(OnActive.InvokeAsync);
        }
    }

    private void OnTimerElapsed(object? sender, System.Timers.ElapsedEventArgs e)
    {
        if (_disposed) return;

        _isIdle = true;
        InvokeAsync(OnIdle.InvokeAsync);
    }

    public async ValueTask DisposeAsync()
    {
        if (_disposed) return;
        _disposed = true;

        if (_timer is not null)
        {
            _timer.Elapsed -= OnTimerElapsed;
            _timer.Stop();
            _timer.Dispose();
            _timer = null;
        }

        if (_jsModule is not null)
        {
            try
            {
                await _jsModule.InvokeVoidAsync("dispose");
                await _jsModule.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
        }

        _dotNetRef?.Dispose();
    }
}

let containerEl = null;
let dotNetRef = null;

const events = ["mousemove", "keydown", "click", "scroll"];

function handleActivity() {
    dotNetRef?.invokeMethodAsync("OnUserActivity");
}

export function initialize(container, ref) {
    containerEl = container;
    dotNetRef = ref;
    for (const evt of events) {
        containerEl.addEventListener(evt, handleActivity, { passive: true });
    }
}

export function dispose() {
    if (containerEl) {
        for (const evt of events) {
            containerEl.removeEventListener(evt, handleActivity);
        }
    }
    containerEl = null;
    dotNetRef = null;
}

